local Players = game:GetService("Players")
local TweenService = game:GetService("TweenService")
local LocalPlayer = Players.LocalPlayer

local SORU = loadstring(game:HttpGet("https://raw.githubusercontent.com/dam45383-netizen/Loader/refs/heads/main/UI.lua"))()
local Window = SORU:CreateWindow({
    Title = "Nexrift",
    Brand = "NEXRIFT",
    Tagline = "Play Smarter.",
})

-- Group Nexrift > Tab Game > Accordion Money
local NexriftGroup = Window:Group({Title = "Nexrift", Icon = "crown"})
local GameTab = NexriftGroup:Tab({Title = "Game", Icon = "gamepad", Subtitle = "Game Features"})
local MoneyAccordion = GameTab:Accordion({Title = "Money", Icon = "dollar", Column = 1})

-- Config
local tweenSpeed = 250
local stopAt = 120
local farming = false
local currentTween = nil
local originalPos = nil
local originalCF = nil

local function findTarget()
    local myName = LocalPlayer.Name
    local fallback = nil
    for _, obj in ipairs(workspace:GetDescendants()) do
        if obj.Name:find("Montors") then
            if obj.Name:find(myName, 1, true) then
                return obj
            elseif not fallback then
                fallback = obj
            end
        end
    end
    return fallback
end

local function getPart(target)
    if target:IsA("BasePart") then
        return target, false
    elseif target:IsA("Model") then
        return target, true
    elseif target:IsA("Folder") then
        local p = target:FindFirstChildWhichIsA("BasePart", true)
        if p then return p, false end
    end
    return nil, false
end

local function tweenTo(target, part, isModel, goalPos)
    local curPos
    if isModel then
        curPos = target:GetPivot().Position
    else
        curPos = part.Position
    end
    local dist = (goalPos - curPos).Magnitude
    local duration = math.max(dist / math.max(tweenSpeed, 1), 0.05)
    local info = TweenInfo.new(duration, Enum.EasingStyle.Linear)
    if isModel then
        local cfVal = Instance.new("CFrameValue")
        cfVal.Value = target:GetPivot()
        local rot = (originalCF and originalCF.Rotation) or target:GetPivot().Rotation
        local toCF = CFrame.new(goalPos) * rot
        local tween = TweenService:Create(cfVal, info, {Value = toCF})
        currentTween = tween
        local conn = cfVal.Changed:Connect(function(v)
            pcall(function() target:PivotTo(v) end)
        end)
        tween:Play()
        tween.Completed:Wait()
        conn:Disconnect()
        cfVal:Destroy()
        currentTween = nil
        return tween.PlaybackState == Enum.PlaybackState.Completed
    else
        local tween = TweenService:Create(part, info, {Position = goalPos})
        currentTween = tween
        tween:Play()
        tween.Completed:Wait()
        currentTween = nil
        return tween.PlaybackState == Enum.PlaybackState.Completed
    end
end

local function fireInteract(seat, target)
    local prompt = nil
    if seat then prompt = seat:FindFirstChildWhichIsA("ProximityPrompt", true) end
    if not prompt and target then prompt = target:FindFirstChildWhichIsA("ProximityPrompt", true) end
    if prompt then
        if fireproximityprompt then
            pcall(fireproximityprompt, prompt)
            return true
        end
        pcall(function()
            prompt:InputHoldBegin()
            task.wait(prompt.HoldDuration or 0)
            prompt:InputHoldEnd()
        end)
        return true
    end
    local cd = seat and seat:FindFirstChildWhichIsA("ClickDetector", true)
    if cd and fireclickdetector then
        pcall(fireclickdetector, cd)
        return true
    end
    local remote = target and target:FindFirstChild("Interact", true)
    if remote and remote:IsA("RemoteEvent") then
        pcall(function() remote:FireServer(seat) end)
        return true
    end
    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    if hum and hrp and seat and seat:IsA("BasePart") then
        hrp.CFrame = seat.CFrame + Vector3.new(0, 1, 0)
        hum.Sit = true
        return true
    end
    return false
end

local function walkToDriveSeat()
    local target = findTarget()
    if not target then return false end
    local seat = target:FindFirstChild("DriveSeat", true)
    if not seat then
        seat = target:FindFirstChildWhichIsA("VehicleSeat", true) or target:FindFirstChildWhichIsA("Seat", true)
    end
    if not seat then return false end
    local char = LocalPlayer.Character
    if not char then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hum or not hrp then return false end
    local seatPos = seat:IsA("BasePart") and seat.Position or seat:GetPivot().Position
    hum:MoveTo(seatPos)
    local start = os.clock()
    while farming and os.clock() - start < 20 do
        if not char.Parent then break end
        if (hrp.Position - seatPos).Magnitude < 5 then break end
        task.wait(0.3)
        if (hrp.Position - seatPos).Magnitude > 5 then
            hum:MoveTo(seatPos)
        end
    end
    return (hrp.Position - seatPos).Magnitude < 8
end

-- RESET YANG BENERAN KE-RESET, ADA TIMEOUT + FALLBACK BUNUH
local function resetCharacter()
    local oldChar = LocalPlayer.Character
    pcall(function() LocalPlayer:LoadCharacter() end)
    task.wait(1.5)
    local newChar = LocalPlayer.Character
    if newChar and newChar ~= oldChar and newChar:FindFirstChild("HumanoidRootPart") then
        return newChar
    end
    -- Fallback: bunuh biar respawn natural
    if newChar then
        local hum = newChar:FindFirstChildOfClass("Humanoid")
        if hum then
            pcall(function() hum.Health = 0 end)
            pcall(function() hum:BreakJoints() end)
        end
    end
    local timeout = os.clock() + 6
    while os.clock() < timeout do
        local c = LocalPlayer.Character
        if c and c ~= oldChar and c:FindFirstChild("HumanoidRootPart") then
            return c
        end
        task.wait(0.2)
    end
    -- Terakhir coba LoadCharacter lagi
    pcall(function() LocalPlayer:LoadCharacter() end)
    task.wait(1)
    return LocalPlayer.Character
end

local function doStopSequence()
    if not farming then return end
    pcall(function() Window.Notify("Stop At", "Park ke -695, 3, -730...") end)
    -- 1. Tween Montors ke -695, 3, -730
    local target = findTarget()
    if target then
        local part, isModel = getPart(target)
        if part then
            pcall(tweenTo, target, part, isModel, Vector3.new(-695, 3, -730))
        end
    end
    task.wait(0.3)
    if not farming then return end

    -- 2. Reset char (udah dibenerin)
    pcall(function() Window.Notify("Stop At", "Reset char...") end)
    local newChar = resetCharacter()
    task.wait(0.5)
    if not newChar then return end
    local hum = newChar:FindFirstChildOfClass("Humanoid")
    if not hum then hum = newChar:WaitForChild("Humanoid", 5) end
    if not hum then return end

    -- 3. WalkTo DriveSeat
    pcall(function() Window.Notify("Stop At", "Jalan ke DriveSeat...") end)
    walkToDriveSeat()
    task.wait(0.3)
    if not farming then return end

    -- 4. Fire interact / ride
    local target2 = findTarget()
    local seat = target2 and (target2:FindFirstChild("DriveSeat", true) or target2:FindFirstChildWhichIsA("VehicleSeat", true) or target2:FindFirstChildWhichIsA("Seat", true))
    fireInteract(seat, target2)
    task.wait(1)
    local hum2 = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
    if hum2 and not hum2.SeatPart then
        fireInteract(seat, target2)
        task.wait(1)
    end
    if not farming then return end

    -- 5. BARU: Kalau sudah ride, ke -749, 2, -638 dulu
    pcall(function() Window.Notify("Stop At", "Udah ride, ke -749, 2, -638 dulu...") end)
    local target3 = findTarget()
    if target3 then
        local part3, isModel3 = getPart(target3)
        if part3 then
            pcall(tweenTo, target3, part3, isModel3, Vector3.new(-749, 2, -638))
            -- Jadikan -749, 2, -638 sebagai posisi awal baru buat bolak-balik berikutnya
            if isModel3 then
                originalCF = target3:GetPivot()
            else
                originalCF = part3.CFrame
            end
            originalPos = Vector3.new(-749, 2, -638)
        end
    end
end

local function farmLoop()
    local cycleStart = os.clock()
    while farming do
        if stopAt > 0 and (os.clock() - cycleStart) >= stopAt then
            pcall(doStopSequence)
            cycleStart = os.clock()
            continue
        end
        local target = findTarget()
        if not target then
            task.wait(0.5)
            continue
        end
        local part, isModel = getPart(target)
        if not part then
            task.wait(0.5)
            continue
        end
        if not originalPos then
            if isModel then
                originalCF = target:GetPivot()
                originalPos = originalCF.Position
            else
                originalPos = part.Position
                originalCF = part.CFrame
            end
        end
        -- Ke X 1000, Y/Z tetep posisi awal (PERSIS SCRIPT LU)
        local to1000 = Vector3.new(1000, originalPos.Y, originalPos.Z)
        local ok = pcall(tweenTo, target, part, isModel, to1000)
        if not farming then break end
        if not ok then task.wait(0.2) continue end
        task.wait(0.1)
        if stopAt > 0 and (os.clock() - cycleStart) >= stopAt then
            pcall(doStopSequence)
            cycleStart = os.clock()
            continue
        end
        -- Balik ke posisi sebelumnya
        pcall(tweenTo, target, part, isModel, originalPos)
        if not farming then break end
        task.wait(0.1)
    end
end

local function startFarm()
    farming = true
    originalPos = nil
    originalCF = nil
    task.spawn(farmLoop)
end

local function stopFarm()
    farming = false
    if currentTween then
        pcall(function() currentTween:Cancel() end)
        currentTween = nil
    end
end

MoneyAccordion:Toggle({
    Title = "Money Farm",
    Desc = "Tween Montors ke X 1000 <-> posisi awal terus menerus",
    Flag = "MoneyFarm",
    Default = false,
    Callback = function(v)
        if v then startFarm() else stopFarm() end
    end
})

MoneyAccordion:Slider({
    Title = "Tween Speed",
    Desc = "Kecepatan tween, 1 paling lambat, 1000 paling cepat",
    Flag = "TweenSpeed",
    Min = 1,
    Max = 1000,
    Step = 1,
    Default = 250,
    Callback = function(v) tweenSpeed = v end
})

MoneyAccordion:Textbox({
    Title = "Stop At (s)",
    Desc = "Tiap berapa detik auto park + reset + naik lagi. 0 = mati",
    Flag = "StopAt",
    Default = 120,
    Placeholder = "120",
    Numeric = true,
